{
  "name": "@bangbang93/opencode-comment-checker",
  "version": "0.1.0",
  "description": "OpenCode plugin that makes the model justify or remove comments it adds with edit and write",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "comment-checker"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "NOTICE.md"
  ],
  "scripts": {
    "test": "node --test index.test.ts",
    "test:bun": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@code-yeongyu/comment-checker": "0.8.2",
    "@opencode/plugin": "^2.4.2"
  }
}

import { spawn } from "node:child_process"
import { createRequire } from "node:module"
import { Plugin } from "@opencode/plugin"

const WARN_GAP_PER_SESSION_MS = 30_000
const CHECK_TIMEOUT_MS = 30_000
// `{{comments}}` expands to the comments the checker detected; undefined keeps its built-in text.
const customPrompt: string | undefined = undefined

type EditToolInput = { path: string; oldString: string; newString: string }
type WriteToolInput = { path: string; content: string }
type CheckerInput =
  | { file_path: string; old_string: string; new_string: string }
  | { file_path: string; content: string }

const require = createRequire(import.meta.url)

function resolveBinary(): string | null {
  try {
    return require("@code-yeongyu/comment-checker").getBinaryPath()
  } catch (error) {
    console.error(`[comment-checker] disabled: ${(error as Error).message}`)
    return null
  }
}

function toCheckerInput(tool: "edit" | "write", input: EditToolInput | WriteToolInput): CheckerInput {
  if (tool === "write") {
    const { path, content } = input as WriteToolInput
    return { file_path: path, content }
  }
  const { path, oldString, newString } = input as EditToolInput
  return { file_path: path, old_string: oldString, new_string: newString }
}

function check(binary: string, toolName: "Edit" | "Write", input: CheckerInput): Promise<string | undefined> {
  const hookInput = {
    session_id: "",
    tool_name: toolName,
    transcript_path: "",
    cwd: process.cwd(),
    hook_event_name: "PostToolUse",
    tool_input: input,
  }
  const args = customPrompt === undefined ? ["check"] : ["check", "--prompt", customPrompt]
  return new Promise((resolve, reject) => {
    const child = spawn(binary, args)
    const timer = setTimeout(() => child.kill("SIGKILL"), CHECK_TIMEOUT_MS)
    let stderr = ""
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString()
    })
    // EPIPE when the checker exits before reading stdin; the exit code still decides the outcome.
    child.stdin.on("error", () => {})
    child.on("error", (error) => {
      clearTimeout(timer)
      reject(error)
    })
    child.on("close", (code) => {
      clearTimeout(timer)
      // The checker signals detected comments with exit code 2 and puts the warning on stderr.
      resolve(code === 2 ? stderr.trim() : undefined)
    })
    child.stdin.end(JSON.stringify(hookInput))
  })
}

function withWarning<T>(content: string | ReadonlyArray<T> | undefined, warning: string) {
  if (content === undefined) return warning
  if (typeof content === "string") return `${content}\n\n${warning}`
  return [...content, { type: "text" as const, text: warning }]
}

export default Plugin.define({
  id: "comment-checker",
  async setup(ctx) {
    let binary = resolveBinary()
    const lastWarningAt = new Map<string, number>()

    await ctx.tool.hook("execute.after", async (event) => {
      if (binary === null || event.status !== "completed") return
      if (event.tool !== "edit" && event.tool !== "write") return
      const last = lastWarningAt.get(event.sessionID) ?? 0
      if (Date.now() - last < WARN_GAP_PER_SESSION_MS) return

      let warning: string | undefined
      try {
        const input = toCheckerInput(event.tool, event.input as EditToolInput | WriteToolInput)
        warning = await check(binary, event.tool === "edit" ? "Edit" : "Write", input)
      } catch (error) {
        binary = null
        console.error(`[comment-checker] disabled: ${(error as Error).message}`)
        return
      }
      if (warning === undefined) return
      lastWarningAt.set(event.sessionID, Date.now())

      event.result = { ...event.result, content: withWarning(event.result.content, warning) }
    })
  },
})
